package dev.astralreach.core;
import java.util.*;

final class BlueprintRewardTests{
 static void run(){
  var claims=new HashSet<String>();var known=new HashSet<String>();var base=new LunarExpedition.Site(91023,0,145);var life=BlueprintExpedition.at(base,BlueprintExpedition.Kind.LIFE_SUPPORT);var rover=BlueprintExpedition.at(base,BlueprintExpedition.Kind.MOBILITY);
  claims.add(BlueprintExpedition.claim(life,0));CoreTests.check(!BlueprintExpedition.reconcile(claims,known),"One life-support record grants no blueprint");
  claims.add(BlueprintExpedition.claim(new BlueprintExpedition.Site(91023,0,1681,life.kind()),1));CoreTests.check(!BlueprintExpedition.reconcile(claims,known),"Records from separate outposts cannot combine across sites");
  claims.add(BlueprintExpedition.claim(rover,1));CoreTests.check(!BlueprintExpedition.reconcile(claims,known),"Different expedition types cannot combine records");
  claims.add(BlueprintExpedition.claim(life,1));CoreTests.check(BlueprintExpedition.reconcile(claims,known)&&known.equals(Set.of(life.kind().id)),"Same-site life-support records unlock only the tank blueprint");
  CoreTests.check(!BlueprintExpedition.reconcile(claims,known),"Repeated completion and reload reconciliation are idempotent");claims.add(BlueprintExpedition.claim(rover,0));CoreTests.check(BlueprintExpedition.reconcile(claims,known)&&known.size()==2,"Mobility records award a distinct permanent rover recipe");
  CoreTests.check(!BlueprintExpedition.completed(Set.of("arbitrary/0","arbitrary/1"),life.kind()),"Malformed keys cannot learn a recipe");CoreTests.check(ExpeditionPerks.fuelReduction(known)==0,"Blueprints never increase the fuel perk or stack unrelated benefits");
  for(var kind:BlueprintExpedition.Kind.values()){
   var site=BlueprintExpedition.nearby(91023,118,-1391,kind);CoreTests.check(site.valid(),"A valid reachable blueprint site can be found");
   for(int i=0;i<2;i++){var p=site.record(i);CoreTests.check(BlueprintExpedition.affectedColumn(site,p.x(),p.z()),"Both mission terminals are included in generation bounds");CoreTests.check(kind.archive.equals(BlueprintExpedition.block(site,p.x(),p.y(),p.z())),"Generated records carry the correct distinct expedition authority");CoreTests.check(!LunarTubes.protectedSite(p.x(),p.z()),"Blueprint sites preserve landing/skylight protections");}
  }
  double normal=OxygenSupply.CAPACITY,large=OxygenSupply.EXTENDED_CAPACITY;CoreTests.check(large==normal*2,"High-capacity canister stores exactly two standard fills");CoreTests.check(OxygenSupply.remaining(large,1200,1,large)==1200&&OxygenSupply.remaining(large,2400,1,large)==0,"Forty-minute normal breathing capacity, no refill on use");CoreTests.check(OxygenSupply.remaining(large,1200,OxygenSupply.rate(true,false),large)==0,"Underwater doubles consumption and yields twenty minutes");CoreTests.check(OxygenSupply.remaining(large,1600,OxygenSupply.rate(false,true),large)==0,"Sprinting preserves the existing 1.5x consumption rate");CoreTests.reject(()->OxygenSupply.remaining(large+1,1,1,large),"Overfilled canister budget is rejected");CoreTests.reject(()->OxygenSupply.remaining(1,1,1,1800),"Unknown canister capacities cannot create oxygen");
  var power=new RoverPower(0);CoreTests.check(power.consume(3,true)==0&&power.units()==0,"An empty rover has no moving power");power.load();long charged=power.units();power.consume(600,false);CoreTests.check(power.units()==charged,"Parking never drains a power cell");power.consume(123.456,true);CoreTests.check(power.units()==776_544_000L,"Movement consumes exact fractional seconds without rounding to whole cells");var saved=new RoverPower(power.units());CoreTests.check(saved.units()==power.units(),"Ordinary rover snapshots retain every microsecond");saved.load();CoreTests.check(!saved.canLoad(),"A full cell cannot overfill or silently discard its remainder");long before=saved.units();CoreTests.reject(saved::load,"Blocked charging must reject");CoreTests.check(saved.units()==before,"Rejected charging keeps the exact energy balance");double powered=saved.consume(2000,true);CoreTests.check(powered>0&&powered<1&&saved.units()==0,"Exhaustion reports only the paid fraction and clamps at zero");CoreTests.reject(()->new RoverPower(-1),"Negative saved energy is invalid");CoreTests.reject(()->new RoverPower(RoverPower.CAPACITY+1),"Overfilled saved energy is invalid");CoreTests.reject(()->power.consume(Double.NaN,true),"Invalid tick time cannot corrupt saved charge");
 }
}
